/**
 * The built-in tutor: a fan-made tribute caricature generated by
 * scripts/build_tutor_avatar.py. Kept free of three.js so app state can
 * reference tutors without loading the 3D engine.
 */
export interface TutorPreset { id: TutorId; label: string; url: string; headScale: number; restingSmile: number }
export type TutorId = "andrej";

export const TUTORS: Record<TutorId, TutorPreset> = {
    andrej: { id: "andrej", label: "Andrej", url: "/avatars/tutor-andrej.vrm", headScale: 1.18, restingSmile: 0.3 },
};
export const DEFAULT_TUTOR: TutorId = "andrej";

export function isTutorId(value: unknown): value is TutorId {
    return typeof value === "string" && value in TUTORS;
}
